per_case_results.actual_sql:
SELECT SUM("amount") FILTER (WHERE "year" = 2019) - SUM("amount") FILTER (WHERE "year" = 2020)
FROM "events"
WHERE "student_club" = 'Student_Club';

SELECT COUNT(*) 
FROM "advertisements" 
WHERE "ad_name" = 'Yearly Kickoff' AND "budget" > (SELECT "budget" FROM "advertisements" WHERE "ad_name" = 'October Meeting');

SELECT "cost" * 100.0 / (SELECT SUM("cost") FROM "events") AS "percentage"
FROM "events"
WHERE "event_name" = 'Yearly Kickoff';

SELECT COUNT(*) AS member_count
FROM "Student_Club"
WHERE "major" = 'Physics Teaching';
